  /// a corrupt sidecar).
  factory ModelCapsStore.fromJson(Map<String, dynamic> json) {
    final caps = <String, ModelCapRecord>{};
    for (final entry in json.entries) {
      final value = entry.value;
      if (value is Map<String, dynamic>) {
