    final first = carriers.removeAt(0);
    final second = carriers.removeAt(0);
    carriers.insert(
      0,
      UserMessage.text('${_carrierTextOf(first)}\n${_carrierTextOf(second)}'),
    );
    merged = [...verbatim, ...carriers, ...messages.sublist(regionEnd)];
