/// [_displacedResults]).
({int nextIndex, List<Message>? unit}) _collectToolGroup(
  List<Message> messages,
  int start,
  int regionEnd,
  Set<int> consumed,
  List<Message> verbatim,
) {
  final message = messages[start] as AssistantMessage;
  final answered = message.content
      .whereType<ToolCall>()
      .map((call) => call.id)
      .toSet();
  final group = <Message>[message];
