Future<_AttemptResult?> _finishedTurnResult(
  AssistantMessage finished,
  Context context,
  AgentLoopConfig config,
  AgentEventSink emit,
  CancelToken? cancelToken,
  _CapHealState capState,
  bool pairingHealed,
  int refusedCount,
